R=C=20
g=[[0]*C for _ in range(R)]
# Original 2 rectangle
for r in range(2,9):
    for c in range(9,16): g[r][c]=2
markers=[(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]
for r,c in markers: g[r][c]=1
# Extend each rectangle row away from any marker on that row; both ways if none.
for r in range(2,9):
    ms=[c for rr,c in markers if rr==r]
    left=not any(c<9 for c in ms)
    right=not any(c>15 for c in ms)
    if left:
        for c in range(0,9):
            if g[r][c]==0: g[r][c]=2
    if right:
        for c in range(16,20):
            if g[r][c]==0: g[r][c]=2
# Extend each rectangle column away from markers above/below; both if none.
for c in range(9,16):
    rs=[r for r,cc in markers if cc==c]
    up=not any(r<2 for r in rs)
    down=not any(r>8 for r in rs)
    if up:
        for r in range(0,2):
            if g[r][c]==0: g[r][c]=2
    if down:
        for r in range(9,20):
            if g[r][c]==0: g[r][c]=2
assert len(g)==20 and all(len(row)==20 for row in g)
assert all(v in range(10) for row in g for v in row)
print(__import__('json').dumps(g,separators=(',',':')))
